from pathlib import Path
root=Path.cwd();p=root/'estruturação do sistema/prototipo-paineis.html';s=p.read_text();s=s.replace('<label>Cliente fictício da demonstração','<label id="actor-label">Pessoa autorizada · demonstração<select id="actor"></select></label><label>Cliente fictício da demonstração')
# Backwards-compatible additive migration, never modifies old records/history.
marker='let state,originalRaw=null'
helpers='''const permissionLabels={read:'Acompanhar chamados',reply:'Responder moradores',update:'Atualizar responsável/prioridade/andamento',close:'Concluir chamados',publish:'Publicar comunicados/documentos',configure:'Configurar etapas da rotina'};
function defaultPolicy(c){const manager={id:c.id+'-manager',name:'Síndico · fictício',function:'Síndico',active:true,permissions:Object.fromEntries(Object.keys(permissionLabels).map(k=>[k,true]))},assistant={id:c.id+'-assistant',name:'Ana · secretária fictícia',function:'Secretária',active:true,permissions:{read:true,reply:true,update:false,close:false,publish:false,configure:false}};return {people:c.id==='A'?[manager,assistant]:[manager],attendants:[manager.id],operationDays:'A definir no exemplo',operationHours:'A definir no exemplo',serviceDays:c.id==='A'?'Segunda a sexta · exemplo':'Segunda e quarta · exemplo',serviceHours:c.id==='A'?'09h às 17h · exemplo':'10h às 16h · exemplo',outside:'Pedido registrado no exemplo. Atendimento no próximo período informado; sem estimativa de resolução confirmada.',history:[]};}
function migratePolicies(v){for(const c of v.clients){if(c.policy===undefined)c.policy=defaultPolicy(c);else if(!c.policy||!Array.isArray(c.policy.people)||!c.policy.people.length||!Array.isArray(c.policy.attendants)||!Array.isArray(c.policy.history)||c.policy.people.some(x=>!x||typeof x.id!=='string'||typeof x.name!=='string'||typeof x.function!=='string'||typeof x.active!=='boolean'||!x.permissions||Object.keys(permissionLabels).some(k=>typeof x.permissions[k]!=='boolean'))||['operationDays','operationHours','serviceDays','serviceHours','outside'].some(k=>typeof c.policy[k]!=='string'))throw Error('Ficha de configuração inválida');}return v;}
'''
s=s.replace(marker,helpers+marker)
s=s.replace('state=originalRaw?validateDemo(JSON.parse(originalRaw)):base()', 'state=migratePolicies(originalRaw?validateDemo(JSON.parse(originalRaw)):base())').replace('catch(e){state=base();persistent=false;', 'catch(e){state=migratePolicies(base());persistent=false;')
s=s.replace("view='carteira',ticketId=null;", "view='carteira',ticketId=null,actorId=null;")
marker="function say(t)"
func='''function actor(){const c=client();return c.policy.people.find(p=>p.id===actorId&&p.active)||c.policy.people.find(p=>p.active)}
function can(key){return role==='carolina'||!!actor()?.permissions[key]}
function policyRecord(c,what,before,after){c.policy.history.push({at:new Date().toISOString(),by:'Carolina · demonstração',what,before,after});}
function ensure(action){if(can(action))return true;say('Esta pessoa não tem permissão para esta ação neste condomínio.');return false;}
'''
s=s.replace(marker,func+marker)
s=s.replace("function updateClients(){", "function updateClients(){const people=client().policy.people.filter(x=>x.active);if(!people.some(x=>x.id===actorId))actorId=people[0]?.id;$('actor').innerHTML=people.map(x=>`<option value=\"${esc(x.id)}\" ${x.id===actorId?'selected':''}>${esc(x.name)} · ${esc(x.function)}</option>`).join('');$('actor-label').hidden=role==='carolina';")
s=s.replace("{carteira:'Carteira',contrato:", "{carteira:'Carteira',ficha:'Cadastro e configuração',contrato:")
s=s.replace("if(!tabs[view])view=", "if(role==='sindico'){if(!can('publish'))delete tabs.conteudos;if(!can('configure'))delete tabs.config;}if(!tabs[view])view=")
s=s.replace("'Seu condomínio'}</p>`", "'Seu condomínio · '+esc(actor()?.name||'Sem pessoa ativa')}</p>`")
s=s.replace("if(role==='sindico'&&!available(c))", "if(role==='sindico'&&(!available(c)||!can('read')))")
s=s.replace("Atendimento ainda não liberado</h3>", "Acesso ao atendimento indisponível</h3>")
# Card with complete individual permission forms, schedule and preserved history.
marker="if(view==='contrato')"
ficha='''if(view==='ficha')s+=`<div class="card"><h3>Pessoas autorizadas neste condomínio</h3><p>Preencher na implantação e editar depois. Cada pessoa tem acesso próprio planejado; nenhum compartilhamento de conta ou login real nesta simulação.</p>${c.policy.people.map(person=>`<form id="personform" data-person="${esc(person.id)}" class="card">${input('person-name-'+person.id,'Nome fictício',person.name)}${input('person-function-'+person.id,'Função neste condomínio',person.function)}<p class="muted">Identificação individual fictícia: ${esc(person.id)}</p><label><input style="width:auto" id="person-active-${esc(person.id)}" type="checkbox" ${person.active?'checked':''}> Vínculo ativo</label>${Object.entries(permissionLabels).map(([key,label])=>`<label><input style="width:auto" id="perm-${esc(person.id)}-${key}" type="checkbox" ${person.permissions[key]?'checked':''}> ${label}</label>`).join('')}<button class="primary">Salvar permissões desta pessoa</button></form>`).join('')}<form id="addperson"><h3>Adicionar pessoa autorizada fictícia</h3>${input('delegate-name','Nome fictício','')}${input('delegate-function','Função, por exemplo secretária','')}<button>Adicionar com permissões inicialmente desmarcadas</button></form><p class="notice">Aprovação de despesas permanece com o síndico conforme configuração autorizada. Não há módulo de despesas neste MVP nem permissão financeira atribuída à secretária por esta ficha.</p></div><form id="scheduleform" class="card"><h3>Funcionamento e atendimento</h3>${input('operation-days','Dias de funcionamento / referência do condomínio',c.policy.operationDays)}${input('operation-hours','Horários de funcionamento / referência',c.policy.operationHours)}${input('service-days','Dias de atendimento',c.policy.serviceDays)}${input('service-hours','Horários de atendimento',c.policy.serviceHours)}<h3>Responsáveis pelo acompanhamento</h3>${c.policy.people.filter(x=>x.active).map(x=>`<label><input style="width:auto" type="checkbox" id="attendant-${esc(x.id)}" ${c.policy.attendants.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}<label>Mensagem fora do expediente<textarea id="outside-message">${esc(c.policy.outside)}</textarea></label><button class="primary">Salvar regras deste condomínio</button><p class="muted">Horários fictícios de revisão; não há relógio de expediente nem envio automático real.</p></form><div class="card"><h3>Histórico de configuração</h3>${c.policy.history.map(h=>`<details><summary>${esc(new Date(h.at).toLocaleString('pt-BR'))} · ${esc(h.by)} · ${esc(h.what)}</summary><p>Antes: ${esc(JSON.stringify(h.before))}</p><p>Depois: ${esc(JSON.stringify(h.after))}</p></details>`).join('')||'<p>Sem alteração registrada. Os exemplos iniciais não inventam alterações anteriores.</p>'}</div>`;
'''
s=s.replace(marker,ficha+marker)
s=s.replace("<button data-action=\"receive\">Simular novo pedido do WhatsApp</button>", "<button data-action=\"receive\">Simular novo pedido do WhatsApp</button> <button data-action=\"receiveOutside\">Simular pedido fora do expediente</button><p class=\"muted\">Atendimento: ${esc(c.policy.serviceDays)} · ${esc(c.policy.serviceHours)}</p>")
s=s.replace("${t.messages.map((m,i)=>", "${t.messages.map((m,i)=>")
s=s.replace("function saveTicket(){", "function saveTicket(requireUpdate=true){if(requireUpdate&&!ensure('update'))return false;")
# A person with reply but no update can send own response without changing all ticket fields.
s=s.replace("if(['respond','close'].includes(d.action)){if(!", "if(['respond','close'].includes(d.action)){if(!ensure(d.action==='close'?'close':'reply'))return;if(!")
s=s.replace("const t=saveTicket();if(!t)return;if(!t.response)", "const t=can('update')?saveTicket():c.tickets.find(x=>x.id===ticketId);if(!t)return;t.response=$('response').value.trim();if(!t.response)")
s=s.replace("t.messages.push('Síndico: '+t.response", "t.messages.push(actor().name+': '+t.response")
s=s.replace("if(d.action==='receive'){", "if(['receive','receiveOutside'].includes(d.action)){if(!ensure('read'))return;")
s=s.replace("ticketId=id;say('Pedido recebido na simulação;", "if(d.action==='receiveOutside')c.tickets.at(-1).messages.push('Mensagem fora do expediente · prévia: '+c.policy.outside);ticketId=id;say('Pedido recebido na simulação;")
s=s.replace("responsible:c.config.responsibles.split(',')[0].trim()", "responsible:c.policy.people.find(x=>c.policy.attendants.includes(x.id)&&x.active)?.name||'Acompanhamento pendente de responsável'")
s=s.replace("if(d.publish){", "if(d.publish){if(!ensure('publish'))return;")
s=s.replace("$('role').onchange=", "$('actor').onchange=e=>{actorId=e.target.value;ticketId=null;view='fila';render();say('Pessoa fictícia selecionada; ações limitadas às permissões configuradas.');};$('role').onchange=")
s=s.replace("view='contrato';render();return", "view='ficha';render();return")
# Handler guards and atomic per-client field/history mutations.
s=s.replace("const c=client();if(e.target.id==='newclient')", "const c=client();if(['personform','addperson','scheduleform'].includes(e.target.id)&&role!=='carolina'){say('Cadastro e permissões são editados na visão Carolina da demonstração.');return;}if(e.target.id==='newclient')")
s=s.replace("state.clients.push(x);selected=x.id;", "x.policy=defaultPolicy(x);state.clients.push(x);selected=x.id;")
marker="if(e.target.id==='paymentform')"
handlers='''if(e.target.id==='personform'){const person=c.policy.people.find(x=>x.id===e.target.dataset.person);if(!person)return;const name=$('person-name-'+person.id).value.trim(),fn=$('person-function-'+person.id).value.trim(),active=$('person-active-'+person.id).checked,permissions=Object.fromEntries(Object.keys(permissionLabels).map(k=>[k,$('perm-'+person.id+'-'+k).checked]));if(!name||!fn){say('Informe nome e função fictícios.');return;}if(active&&permissions.reply&&!permissions.read){say('Para responder moradores, autorize também acompanhar chamados.');return;}const before=JSON.parse(JSON.stringify(person));Object.assign(person,{name,function:fn,active,permissions});policyRecord(c,'Pessoa/permissões alteradas',before,JSON.parse(JSON.stringify(person)));say('Vínculo e permissões atualizados só neste condomínio, com histórico.');}
if(e.target.id==='addperson'){const name=$('delegate-name').value.trim(),fn=$('delegate-function').value.trim();if(!name||!fn){say('Informe nome e função fictícios.');return;}const person={id:c.id+'-person-'+Date.now()+'-'+Math.random().toString(36).slice(2),name,function:fn,active:true,permissions:Object.fromEntries(Object.keys(permissionLabels).map(k=>[k,false]))};c.policy.people.push(person);policyRecord(c,'Pessoa autorizada cadastrada',null,person);say('Pessoa fictícia criada com identificação própria; configure as permissões necessárias.');}
if(e.target.id==='scheduleform'){const fields={operationDays:$('operation-days').value.trim(),operationHours:$('operation-hours').value.trim(),serviceDays:$('service-days').value.trim(),serviceHours:$('service-hours').value.trim(),outside:$('outside-message').value.trim(),attendants:c.policy.people.filter(x=>x.active&&$('attendant-'+x.id).checked).map(x=>x.id)};if(!fields.serviceDays||!fields.serviceHours||!fields.outside||!fields.attendants.length){say('Informe dias/horários, mensagem e ao menos um responsável real do exemplo.');return;}const keys=Object.keys(fields),before=Object.fromEntries(keys.map(k=>[k,c.policy[k]]));Object.assign(c.policy,fields);policyRecord(c,'Regras de funcionamento/atendimento alteradas',before,fields);say('Horários, responsáveis e mensagem salvos neste condomínio com autoria/data.');}
'''
s=s.replace(marker,handlers+marker)
s=s.replace("if(e.target.id==='contentform'){", "if(e.target.id==='contentform'){if(!ensure('publish'))return;")
s=s.replace("if(e.target.id==='configform'){", "if(e.target.id==='configform'){if(!ensure('configure'))return;")
s=s.replace("state=base();selected=", "state=migratePolicies(base());selected=")
